const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Fixtures implement the Source/Lease contract in src/source.ts.
function fixture(options = {}) {
  const { values = ['a', 'b', null], readError, closeError, mapper } = options;
  const counts = { opens: 0, reads: 0, closes: 0 };
  const service = new EventService({
    open: async () => {
      counts.opens++;
      return {
        read: async () => {
          counts.reads++;
          if (Object.hasOwn(options, 'readError')) throw readError;
          return values.shift();
        },
        close: async () => {
          counts.closes++;
          if (closeError !== undefined) throw closeError;
        },
      };
    },
  }, mapper);
  return { stream: service.stream(), counts };
}

async function rejectsWith(action, expected) {
  let rejected = false;
  try {
    await action();
  } catch (error) {
    rejected = true;
    assert.equal(error, expected);
  }
  assert.equal(rejected, true, 'expected rejection');
}

async function main() {
  {
    const { stream, counts } = fixture();
    assert.deepEqual(counts, { opens: 0, reads: 0, closes: 0 });
    await stream.return();
    assert.deepEqual(counts, { opens: 0, reads: 0, closes: 0 });
    assert.equal((await stream.next()).done, true);
  }
  {
    const { stream, counts } = fixture();
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    assert.deepEqual(counts, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.deepEqual(counts, { opens: 1, reads: 2, closes: 0 });
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(counts, { opens: 1, reads: 3, closes: 1 });
    await stream.next();
    await stream.return();
    assert.deepEqual(counts, { opens: 1, reads: 3, closes: 1 });
  }
  for (const closeError of [undefined, new Error('close failed')]) {
    for (const ending of ['exhaust', 'break', 'return']) {
      const { stream, counts } = fixture({ closeError });
      const consume = async () => {
        if (ending === 'return') {
          await stream.next();
          assert.deepEqual(await stream.return('finished'), { value: 'finished', done: true });
        } else {
          const found = [];
          for await (const value of stream) {
            found.push(value);
            if (ending === 'break') break;
          }
          assert.deepEqual(found, ending === 'break' ? ['A'] : ['A', 'B']);
        }
      };
      if (closeError) await rejectsWith(consume, closeError);
      else await consume();
      assert.deepEqual(counts, { opens: 1, reads: ending === 'exhaust' ? 3 : 1, closes: 1 });
      await stream.return();
      assert.equal(counts.closes, 1);
    }
    for (const failure of ['read', 'mapper', 'throw']) {
      // Also ensure falsy thrown values are not mistaken for absence of an error.
      for (const original of [new Error(failure), undefined, null, 0]) {
        const options = { closeError };
        if (failure === 'mapper') options.mapper = () => { throw original; };
        if (failure === 'read') options.readError = original;
        const { stream, counts } = fixture(options);
        if (failure === 'throw') {
          await stream.next();
          await rejectsWith(() => stream.throw(original), original);
        } else {
          await rejectsWith(() => stream.next(), original);
        }
        assert.deepEqual(counts, { opens: 1, reads: 1, closes: 1 });
        await stream.next();
        await stream.return();
        assert.equal(counts.closes, 1);
      }
    }
  }
  {
    const error = new Error('open failed');
    let opens = 0;
    const stream = new EventService({ open: async () => { opens++; throw error; } }).stream();
    assert.equal(opens, 0);
    await rejectsWith(() => stream.next(), error);
    assert.equal(opens, 1);
    await stream.return();
    assert.equal(opens, 1);
  }
}

module.exports = main();

